WITH flattened_attrs AS (SELECT id, service, host, log_ts, level, latency_ms, status_code, payload_json, context, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration AS duration_sec, COALESCE(context['trace'], 'unknown') AS trace_or_default, context['trace'] AS trace FROM app_logs) SELECT *, ROW_NUMBER() OVER (PARTITION BY service ORDER BY latency_ms DESC, id ASC) row_seq, DENSE_RANK() OVER (ORDER BY duration_sec DESC NULLS FIRST) duration_sec_dense_rank, CORR(latency_ms, status_code) OVER w_ordered corr_latency_ms_status_code FROM flattened_attrs WINDOW w_ordered AS (PARTITION BY service)
